import json
import re
from dataclasses import dataclass
from typing import Any

from family_agent.evals.fixtures import (
    ExpectedToolArgumentSubset,
    FamilyAgentEvalScenario,
)
from family_agent.proposal_types import normalize_family_agent_proposal_type
from family_agent.tool_request_schemas import TOOL_REQUEST_REGISTRY

_OFFSET_RE = re.compile(r"T\d{2}:\d{2}:\d{2}(?:Z|[+-]\d{2}:\d{2})$")
_APPROVAL_COPY_RE = re.compile(
    r"\b(prepared|ready|pending|for approval|approve)\b", flags=re.IGNORECASE
)


@dataclass(frozen=True)
class FamilyAgentEvalGateResult:
    name: str
    passed: bool
    message: str

    def to_dict(self) -> dict[str, Any]:
        return {
            "name": self.name,
            "passed": self.passed,
            "message": self.message,
        }


def _tool_calls(response: dict[str, Any]) -> list[dict[str, Any]]:
    usage_json = response.get("usage_json")
    if not isinstance(usage_json, dict):
        return []
    calls = usage_json.get("availability_tool_calls")
    if not isinstance(calls, list):
        return []
    return [call for call in calls if isinstance(call, dict)]


def _tool_call_names(response: dict[str, Any]) -> list[str]:
    return [str(call.get("name") or "") for call in _tool_calls(response)]


def _proposals(response: dict[str, Any]) -> list[dict[str, Any]]:
    proposals = response.get("proposals")
    if not isinstance(proposals, list):
        return []
    return [proposal for proposal in proposals if isinstance(proposal, dict)]


def _action_suggestions(response: dict[str, Any]) -> list[dict[str, Any]]:
    suggestions = response.get("action_suggestions")
    if not isinstance(suggestions, list):
        return []
    return [suggestion for suggestion in suggestions if isinstance(suggestion, dict)]


def _contains_argument_subset(
    *, calls: list[dict[str, Any]], subset: ExpectedToolArgumentSubset
) -> bool:
    for call in calls:
        if str(call.get("name") or "") != subset.name:
            continue
        arguments = call.get("arguments")
        if not isinstance(arguments, dict):
            continue
        if all(arguments.get(key) == value for key, value in subset.arguments.items()):
            return True
    return False


def _iter_temporal_values(value: Any) -> list[str]:
    temporal_values: list[str] = []
    if isinstance(value, dict):
        for key, nested_value in value.items():
            if key in {"start_time", "end_time", "selected_slot_start"}:
                temporal_values.append(str(nested_value))
            else:
                temporal_values.extend(_iter_temporal_values(nested_value))
    elif isinstance(value, list):
        for item in value:
            temporal_values.extend(_iter_temporal_values(item))
    return temporal_values


def _serialized_response(response: dict[str, Any]) -> str:
    return json.dumps(response, sort_keys=True, default=str)


def evaluate_family_agent_eval_result(
    *, scenario: FamilyAgentEvalScenario, response: dict[str, Any]
) -> list[FamilyAgentEvalGateResult]:
    expected = scenario.expected
    gate_results: list[FamilyAgentEvalGateResult] = []
    calls = _tool_calls(response)
    call_names = _tool_call_names(response)
    proposals = _proposals(response)
    proposal_types = [
        str(proposal.get("proposal_type") or "") for proposal in proposals
    ]
    normalized_proposal_types = [
        normalize_family_agent_proposal_type(proposal_type)
        for proposal_type in proposal_types
    ]
    suggestions = _action_suggestions(response)
    suggestion_types = [str(suggestion.get("type") or "") for suggestion in suggestions]
    response_text = str(response.get("assistant_text") or "")
    response_blob = _serialized_response(response)

    if "required_tools" in expected.hard_gates:
        missing = sorted(set(expected.required_tool_names) - set(call_names))
        gate_results.append(
            FamilyAgentEvalGateResult(
                name="required_tools",
                passed=not missing,
                message="Required tools were called."
                if not missing
                else f"Missing tools: {missing}",
            )
        )

    if "allowed_tools" in expected.hard_gates or expected.allowed_tool_names:
        unexpected = sorted(set(call_names) - set(expected.allowed_tool_names))
        gate_results.append(
            FamilyAgentEvalGateResult(
                name="allowed_tools",
                passed=not unexpected,
                message="Only allowed tools were called."
                if not unexpected
                else f"Unexpected tools: {unexpected}",
            )
        )

    if expected.forbidden_tool_names:
        forbidden = sorted(set(call_names) & set(expected.forbidden_tool_names))
        gate_results.append(
            FamilyAgentEvalGateResult(
                name="forbidden_tools",
                passed=not forbidden,
                message="No forbidden tools were called."
                if not forbidden
                else f"Forbidden tools called: {forbidden}",
            )
        )

    for subset in expected.expected_tool_argument_subsets:
        passed = _contains_argument_subset(calls=calls, subset=subset)
        gate_results.append(
            FamilyAgentEvalGateResult(
                name=f"tool_arguments:{subset.name}",
                passed=passed,
                message="Expected tool arguments were present."
                if passed
                else f"Missing expected arguments for {subset.name}: {subset.arguments}",
            )
        )

    if "valid_tool_args" in expected.hard_gates:
        invalid_messages: list[str] = []
        for call in calls:
            tool_name = str(call.get("name") or "")
            arguments = call.get("arguments") or {}
            entry = TOOL_REQUEST_REGISTRY.get(tool_name)
            if entry is None:
                invalid_messages.append(f"{tool_name}: unsupported tool")
                continue
            serializer = entry[1](data=arguments)
            if not serializer.is_valid():
                invalid_messages.append(f"{tool_name}: {serializer.errors}")
        gate_results.append(
            FamilyAgentEvalGateResult(
                name="valid_tool_args",
                passed=not invalid_messages,
                message="Tool arguments matched registry schemas."
                if not invalid_messages
                else "; ".join(invalid_messages),
            )
        )

    if expected.max_proposals is not None:
        passed = len(proposals) <= expected.max_proposals
        gate_results.append(
            FamilyAgentEvalGateResult(
                name="max_proposals",
                passed=passed,
                message=f"Proposal count <= {expected.max_proposals}."
                if passed
                else f"Proposal count {len(proposals)} exceeds {expected.max_proposals}.",
            )
        )

    if "no_proposals" in expected.hard_gates:
        gate_results.append(
            FamilyAgentEvalGateResult(
                name="no_proposals",
                passed=not proposals,
                message="No proposals were emitted."
                if not proposals
                else "Unexpected proposals were emitted.",
            )
        )

    if "proposal_types" in expected.hard_gates or expected.expected_proposal_types:
        expected_types = list(expected.expected_proposal_types)
        normalized_actual = [
            item for item in normalized_proposal_types if item is not None
        ]
        type_mismatch = normalized_actual != expected_types
        unsupported = [
            item
            for item, normalized in zip(
                proposal_types,
                normalized_proposal_types,
                strict=True,
            )
            if normalized is None
        ]
        forbidden = sorted(set(proposal_types) & set(expected.forbidden_proposal_types))
        passed = not type_mismatch and not unsupported and not forbidden
        gate_results.append(
            FamilyAgentEvalGateResult(
                name="proposal_types",
                passed=passed,
                message="Proposal types matched expectations."
                if passed
                else (
                    f"expected={expected_types} actual={proposal_types} "
                    f"unsupported={unsupported} forbidden={forbidden}"
                ),
            )
        )

    if "action_suggestions" in expected.hard_gates:
        missing = sorted(
            set(expected.expected_action_suggestion_types) - set(suggestion_types)
        )
        gate_results.append(
            FamilyAgentEvalGateResult(
                name="action_suggestions",
                passed=not missing,
                message="Expected action suggestions were present."
                if not missing
                else f"Missing action suggestion types: {missing}",
            )
        )

    if expected.required_terms:
        missing_terms = [
            term
            for term in expected.required_terms
            if term.lower() not in response_blob.lower()
        ]
        gate_results.append(
            FamilyAgentEvalGateResult(
                name="required_terms",
                passed=not missing_terms,
                message="Required terms were present."
                if not missing_terms
                else f"Missing required terms: {missing_terms}",
            )
        )

    if (
        expected.forbidden_terms
        or "forbidden_terms" in expected.hard_gates
        or "privacy_terms" in expected.hard_gates
    ):
        forbidden_terms = [
            term
            for term in expected.forbidden_terms
            if term.lower() in response_blob.lower()
        ]
        gate_results.append(
            FamilyAgentEvalGateResult(
                name="forbidden_terms",
                passed=not forbidden_terms,
                message="Forbidden terms were absent."
                if not forbidden_terms
                else f"Forbidden terms present: {forbidden_terms}",
            )
        )

    if expected.requires_timezone_offsets or "timezone_offsets" in expected.hard_gates:
        temporal_values = _iter_temporal_values(calls) + _iter_temporal_values(
            proposals
        )
        missing_offsets = [
            value
            for value in temporal_values
            if "T" in value and not _OFFSET_RE.search(value)
        ]
        gate_results.append(
            FamilyAgentEvalGateResult(
                name="timezone_offsets",
                passed=not missing_offsets,
                message="Temporal values include explicit offsets."
                if not missing_offsets
                else f"Temporal values missing offsets: {missing_offsets}",
            )
        )

    if "out_of_scope" in expected.hard_gates or expected.out_of_scope:
        usage_json = (
            response.get("usage_json")
            if isinstance(response.get("usage_json"), dict)
            else {}
        )
        passed = (
            usage_json.get("request_scope") == "out_of_scope"
            and usage_json.get("model_call_count", 0) == 0
        )
        gate_results.append(
            FamilyAgentEvalGateResult(
                name="out_of_scope",
                passed=passed,
                message="Request was rejected before model call."
                if passed
                else f"Unexpected usage_json for out-of-scope request: {usage_json}",
            )
        )

    if "no_tools" in expected.hard_gates:
        gate_results.append(
            FamilyAgentEvalGateResult(
                name="no_tools",
                passed=not calls,
                message="No tool calls were made."
                if not calls
                else f"Unexpected tool calls: {call_names}",
            )
        )

    if "proposal_copy_consistency" in expected.hard_gates:
        valid_proposals = [
            proposal
            for proposal in proposals
            if normalize_family_agent_proposal_type(proposal.get("proposal_type"))
            is not None
        ]
        approval_copy_without_valid_proposal = (
            bool(_APPROVAL_COPY_RE.search(response_text)) and not valid_proposals
        )
        gate_results.append(
            FamilyAgentEvalGateResult(
                name="proposal_copy_consistency",
                passed=not approval_copy_without_valid_proposal,
                message="Approval copy has a valid structured proposal."
                if not approval_copy_without_valid_proposal
                else "Assistant text implies approval readiness without a valid proposal.",
            )
        )

    return gate_results
